SELECT count(*) AS net_visitors
FROM agg_daily_users
WHERE summary_date = current_date - 1;

SELECT traffic_source,
       COALESCE(sum(sessions) FILTER (
           WHERE summary_date >= DATE '2026-11-09' AND summary_date < DATE '2026-11-16'
       ), 0) AS this_week_sessions,
       COALESCE(sum(sessions) FILTER (
           WHERE summary_date >= DATE '2026-11-02' AND summary_date < DATE '2026-11-09'
       ), 0) AS last_week_sessions,
       COALESCE(sum(sessions) FILTER (
           WHERE summary_date >= DATE '2026-11-09' AND summary_date < DATE '2026-11-16'
       ), 0) - COALESCE(sum(sessions) FILTER (
           WHERE summary_date >= DATE '2026-11-02' AND summary_date < DATE '2026-11-09'
       ), 0) AS week_over_week_diff
FROM agg_traffic_hourly
WHERE summary_date >= DATE '2026-11-02' AND summary_date < DATE '2026-11-16'
GROUP BY traffic_source
ORDER BY this_week_sessions DESC, traffic_source;
